with lines as (select id, host, log_ts, level, latency_ms, status_code, attr_key, v from app_logs lateral view explode(context) e as attr_key, v) select id, host, log_ts, level, latency_ms, status_code, attr_key, v, sum(latency_ms) over w_ordered running_latency_ms, lag(status_code, 1) over w_running prev_status_code from lines window w_ordered as (partition by attr_key order by status_code, id, attr_key rows between unbounded preceding and current row), w_running as (partition by host order by log_ts, id, attr_key)
